  /**
   * Preserve the recorded answer while attention distinguishes delivery intent
   * from confirmation. A failed delivery does not prove a callback can be retried.
   */
  const dispatchRuntimeRequestDeliveryReceipt = Effect.fn(
    "Orchestrator.dispatchRuntimeRequestDeliveryReceipt",
  )(function* (
    command: Extract<
      OrchestrationV2InternalCommand,
      { readonly type: "runtime-request.delivery.fail" | "runtime-request.delivery.confirm" }
    >,
    events: Ref.Ref<Array<OrchestrationV2DomainEvent>>,
  ) {
    const thread = yield* projectionStore
      .getThread(command.threadId)
      .pipe(mapDispatchError(command));
    if (thread.deletedAt !== null) return;
    const responseContext = yield* projectionStore
      .getRuntimeResponseContext(command.threadId, command.requestId)
      .pipe(mapDispatchError(command));
    const node = responseContext.node;
    if (node === undefined) return;
    const now = yield* DateTime.now;
    const request = responseContext.request;
    if (request === undefined || request.responseDelivery === "confirmed") return;
    if (request.responseDelivery === "pending")
      yield* emit(
        events,
        command,
      )({
        type: "runtime-request.updated",
        threadId: command.threadId,
        nodeId: node.id,
        occurredAt: now,
        payload: {
          ...request,
          responseDelivery:
            command.type === "runtime-request.delivery.confirm" ? "confirmed" : "failed",
        },
      });
    if (command.type === "runtime-request.delivery.confirm") return;
    yield* emit(
      events,
      command,
    )({
      type: "turn-item.updated",
      threadId: command.threadId,
      ...(node.runId === null ? {} : { runId: node.runId }),
      nodeId: node.id,
      providerInstanceId: thread.providerInstanceId,
      occurredAt: now,
      payload: {
        id: TurnItemId.make(`turn-item:runtime-request-delivery-failure:${command.requestId}`),
        threadId: command.threadId,
        runId: node.runId,
        nodeId: node.id,
        providerThreadId: node.providerThreadId,
        providerTurnId: node.providerTurnId,
        nativeItemRef: null,
        parentItemId: null,
        ordinal: yield* nextTurnItemOrdinal({ thread }),
        status: "failed",
        title: "Answer delivery not confirmed",
        startedAt: now,
        completedAt: now,
        updatedAt: now,
        type: "error",
        failure: {
          class: "transport_error",
          message: RUNTIME_REQUEST_DELIVERY_FAILED_MESSAGE,
          code: null,
          retryable: null,
        },
      },
    });
  });

  const dispatchThreadUserInputDismiss = Effect.fn("Orchestrator.dispatchThreadUserInputDismiss")(
