      .pipe(Effect.mapError(() => new OrchestratorProjectionError({ threadId: command.threadId })));
    const queuedRun = projection.runs.find((candidate) => candidate.id === command.runId);
    if (queuedRun === undefined || queuedRun.status !== "queued") {
