              break;
            }
            case "node.updated": {
              const payloadJson = yield* encodeNodePayload(event.payload);
              const payload = parseEncodedPayload(payloadJson);
              yield* sql`
              INSERT INTO orchestration_v2_projection_nodes (
                node_id,
